/bin/bash -lc "python -c 'import csv; inp=\"galaxy_outputs/FeMinus_results.tsv\"; out=\"galaxy_outputs/FeMinus_upregulated.tsv\"; n=0; fi=open(inp); fo=open(out,\"w\"); rd=csv.DictReader(fi,delimiter=\"\\t\"); fo.write(\"gene_id\\n\");
for row in rd:
  try: keep=float(row[\"log2FoldChange\"])>1.5 and float(row[\"padj\"])<0.05
  except (ValueError,TypeError): keep=False
  if keep: fo.write(row[\"rowname\"]+\"\\n\"); n+=1
fi.close(); fo.close(); print(n)'"
